SELECT 
FROM app_android_release
WHERE app_id = #{appId}
  AND package_name = #{packageName}
  AND channel_code = #{channelCode}
  AND status = 'PUBLISHED'
  AND (publish_at IS NULL OR publish_at <= CURRENT_TIMESTAMP)
ORDER BY version_code DESC, id DESC
LIMIT 1

SELECT COUNT(*) FROM app_android_release
(version_name LIKE CONCAT('%', #{keyword}, '%') OR package_name LIKE CONCAT('%', #{keyword}, '%') OR title LIKE CONCAT('%', #{keyword}, '%'))
AND status = #{status}

SELECT FROM app_android_release
(version_name LIKE CONCAT('%', #{keyword}, '%') OR package_name LIKE CONCAT('%', #{keyword}, '%') OR title LIKE CONCAT('%', #{keyword}, '%'))
AND status = #{status}
ORDER BY version_code DESC, id DESC LIMIT #{limit} OFFSET #{offset}

